VALUES ('55d9d055-f12a-56ed-bfd9-24156b257072', '57deaf37-eb40-560a-a2fb-32165bad7ceb', 1, $json${"prompt":"When would adding a B-tree index to a PostgreSQL column likely NOT help?","multiple":false,"options":[{"id":"a","text":"When the column has very low selectivity (few distinct values)","is_correct":true},{"id":"b","text":"When the table has millions of rows","is_correct":false},{"id":"c","text":"When queries filter on that column with equality","is_correct":false},{"id":"d","text":"When queries sort by that column","is_correct":false}],"explanation":"If a filter matches a large fraction of rows (low selectivity), the planner prefers a sequential scan — the index adds write cost without read benefit."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

