INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('0a2c2895-34b7-582a-8ef5-106d5809a229', '9a360853-0152-5de9-bf23-ac351ea5bff1', 1, $json${"prompt":"Topological sort is only defined for which kind of graph?","multiple":false,"options":[{"id":"a","text":"Directed acyclic graphs (DAGs)","is_correct":true},{"id":"b","text":"Undirected connected graphs","is_correct":false},{"id":"c","text":"Weighted graphs","is_correct":false},{"id":"d","text":"Complete graphs","is_correct":false}],"explanation":"A topological order requires directed edges and no cycles — a cycle makes any linear ordering impossible, which is why Course Schedule reduces to cycle detection."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

