INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('691dcdcb-31b6-57e3-a92d-56118639c5cd', '7b497235-9227-5859-a332-f8a3dfe8c285', 1, $json${"prompt":"Why can you reconstruct a binary tree from preorder + inorder traversals, but not from preorder alone?","multiple":false,"options":[{"id":"a","text":"Preorder gives the root order, but inorder is needed to split left and right subtrees","is_correct":true},{"id":"b","text":"Preorder alone loses the values of leaf nodes","is_correct":false},{"id":"c","text":"Inorder is needed to know the tree's height","is_correct":false},{"id":"d","text":"You actually can reconstruct it from preorder alone","is_correct":false}],"explanation":"Preorder tells you each subtree's root, but without inorder you can't tell which following nodes belong to the left vs right subtree — multiple trees share the same preorder."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

