INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('d7cc6cdf-5efb-5150-a4b6-79ce82b4775b', '7f3b1921-2cb5-53dc-9631-348023d29b91', 1, $json${"prompt":"In a Twitter-style feed design, what is the main trade-off between fan-out-on-write and fan-out-on-read?","multiple":false,"options":[{"id":"a","text":"Fan-out-on-write precomputes timelines for fast reads but is expensive for accounts with millions of followers","is_correct":true},{"id":"b","text":"Fan-out-on-read is always cheaper in every dimension","is_correct":false},{"id":"c","text":"Fan-out-on-write reduces storage usage","is_correct":false},{"id":"d","text":"There is no difference for celebrity accounts","is_correct":false}],"explanation":"Pushing each tweet into every follower's timeline makes reads O(1) but writes explode for celebrities — real systems use a hybrid: fan-out-on-write for normal users, fan-out-on-read for high-follower accounts."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

