INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('efe8a70f-c80d-5271-8bbd-01e0a549501f', 'f66c483c-5734-516e-9bab-e415f3f1cb81', 1, $json${"prompt":"Which HTTP method semantics are correct for a REST API?","multiple":false,"options":[{"id":"a","text":"PUT replaces a resource idempotently; PATCH applies a partial update; POST creates without idempotency","is_correct":true},{"id":"b","text":"POST is idempotent; PUT is not","is_correct":false},{"id":"c","text":"PATCH fully replaces the resource","is_correct":false},{"id":"d","text":"PUT and POST are interchangeable by spec","is_correct":false}],"explanation":"PUT sends the full replacement representation and repeated calls give the same result; PATCH sends only changed fields; POST creates a new resource each call, so retries need idempotency keys."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

