INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('55f46b32-2040-5007-9e58-95530f210acd', '356bf9dc-93fd-597a-900c-2afaf13e5b20', 1, $json${"prompt":"In a job queue system, how do you safely handle a worker that dies mid-task?","multiple":false,"options":[{"id":"a","text":"Use visibility timeouts / heartbeats so the job returns to the queue, and make task handlers idempotent","is_correct":true},{"id":"b","text":"Mark the job completed as soon as a worker picks it up","is_correct":false},{"id":"c","text":"Delete the job when the worker crashes","is_correct":false},{"id":"d","text":"Rely on the worker to always finish","is_correct":false}],"explanation":"Acknowledge only after completion; if the worker's lease or heartbeat lapses, the broker redelivers. Because redelivery means possible re-execution, handlers must be idempotent — the core Celery interview answer."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

