VALUES ('48758ddc-2038-514d-846a-176883fe84ea', '603da097-ce96-576a-b184-43b0df516da0', 1, $json${"prompt":"What is the worst-case time complexity of generating all subsets via backtracking?","multiple":false,"options":[{"id":"a","text":"O(n · 2ⁿ)","is_correct":true},{"id":"b","text":"O(n²)","is_correct":false},{"id":"c","text":"O(n log n)","is_correct":false},{"id":"d","text":"O(2ⁿ / n)","is_correct":false}],"explanation":"There are 2ⁿ subsets and copying each one costs up to O(n) — exponential output means exponential time, which is why pruning matters so much in backtracking."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

