VALUES ('b6d8014e-93d4-5ac5-bad3-1916314590d0', '15c5e349-90eb-504a-91c6-d50cede64343', 1, $json${"prompt":"Which XOR properties make Single Number solvable in O(n) time and O(1) space?","multiple":false,"options":[{"id":"a","text":"a ⊕ a = 0 and a ⊕ 0 = a","is_correct":true},{"id":"b","text":"a ⊕ b = a + b","is_correct":false},{"id":"c","text":"XOR is not commutative, which isolates the answer","is_correct":false},{"id":"d","text":"a ⊕ a = a","is_correct":false}],"explanation":"XOR-ing everything cancels each paired value to 0, and 0 ⊕ x = x leaves exactly the unpaired element."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

