INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('83051ca1-7ce6-5b0b-8b85-dc235cac4726', '712549bb-5458-5e23-9770-b6e7d080d4a4', 1, $json${"prompt":"In fixed-width integer languages, how do you compute a binary-search midpoint without overflow?","multiple":false,"options":[{"id":"a","text":"mid = low + (high − low) / 2","is_correct":true},{"id":"b","text":"mid = (low + high) / 2 — it can never overflow","is_correct":false},{"id":"c","text":"mid = high / 2 + low","is_correct":false},{"id":"d","text":"Use floating point and round","is_correct":false}],"explanation":"(low + high) can exceed the integer max when both are large; low + (high − low)/2 keeps every intermediate value in range. A classic math-and-edge-cases interview probe."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
