INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('87b0b40a-1a55-525c-b307-88e587d7f99d', '2971f5da-855a-5f5b-bf50-73c605a1cc3e', 1, $json${"prompt":"In a system design interview, what comes immediately after gathering functional requirements?","multiple":false,"options":[{"id":"a","text":"Back-of-the-envelope estimation — users, QPS, storage, read/write ratio","is_correct":true},{"id":"b","text":"Choosing the programming language","is_correct":false},{"id":"c","text":"Drawing the final architecture with every microservice","is_correct":false},{"id":"d","text":"Writing the database schema in full detail","is_correct":false}],"explanation":"Scale numbers drive every later decision: 100 QPS and 100k QPS produce different designs. Estimating first keeps you from designing for a scale the interviewer never asked about."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

