INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('dfe19636-649d-525e-9a09-ed3543ad5b9e', 'b99e3751-ccb6-548b-997c-a42231c79b99', 1, $json${"prompt":"Designing a Twitter-like feed: what is the core trade-off between fan-out-on-write and fan-out-on-read?","multiple":false,"options":[{"id":"a","text":"Write fan-out precomputes timelines for fast reads but wastes work for celebrity accounts; read fan-out queries followees at read time","is_correct":true},{"id":"b","text":"Read fan-out is always faster for every account size","is_correct":false},{"id":"c","text":"Write fan-out means tweets are stored twice for durability","is_correct":false},{"id":"d","text":"There is no difference — both cost the same","is_correct":false}],"explanation":"Push (write fan-out) makes reads O(1) but a 100M-follower account triggers 100M timeline inserts per tweet. The classic hybrid: push for normal users, pull-and-merge for celebrities."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

