INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('e61042d1-c2de-514a-b35f-40fcdbd4296d', '099655cc-bedf-5395-86a4-05acbba9a6bd', 1, $json${"prompt":"What is the STAR format for behavioral answers?","multiple":false,"options":[{"id":"a","text":"Situation, Task, Action, Result","is_correct":true},{"id":"b","text":"Strengths, Talents, Achievements, References","is_correct":false},{"id":"c","text":"Summary, Timeline, Analysis, Reflection","is_correct":false},{"id":"d","text":"Situation, Team, Attitude, Response","is_correct":false}],"explanation":"STAR keeps behavioral answers concrete and scoped: set the scene briefly, state your responsibility, spend most time on YOUR actions, and land on a measurable result."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

