VALUES ('016c40f5-c1dc-5ca3-8d05-e98da782abe4', '00000000-0000-0000-0000-000000000001', 'mcq', 'You''re stuck on a mock-interview problem for several minutes. Best move?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4841a2c1-42f2-5d41-ac6a-ab1475b8a99a', '016c40f5-c1dc-5ca3-8d05-e98da782abe4', 1, $json${"prompt":"You're stuck on a mock-interview problem for several minutes. Best move?","multiple":false,"options":[{"id":"a","text":"Talk through what you know, name the pattern you suspect, and solve a simpler version out loud","is_correct":true},{"id":"b","text":"Go silent until you find the optimal solution","is_correct":false},{"id":"c","text":"Give up and ask for the answer","is_correct":false},{"id":"d","text":"Write code randomly hoping it compiles into insight","is_correct":false}],"explanation":"Silence is the worst signal in an interview. Verbalizing partial progress shows your debugging process and invites the interviewer's calibrated hints — which they want to give."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('14c05087-98fa-59b6-8f54-4257a1ff4145', '00000000-0000-0000-0000-000000000001', 'mcq', 'Designing YouTube-scale video storage, the standard serving approach is:', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('a07254f1-2816-56e7-8a4f-ee853fa3c732', '14c05087-98fa-59b6-8f54-4257a1ff4145', 1, $json${"prompt":"Designing YouTube-scale video storage, the standard serving approach is:","multiple":false,"options":[{"id":"a","text":"Store transcoded segments in blob storage and serve through a CDN, keeping metadata in a database","is_correct":true},{"id":"b","text":"Store video bytes as BLOB columns in PostgreSQL","is_correct":false},{"id":"c","text":"Stream every request from the original upload server","is_correct":false},{"id":"d","text":"Keep all videos in Redis for speed","is_correct":false}],"explanation":"Video bytes belong in object storage (S3-style), delivered from CDN edges near users; databases hold only metadata (title, owner, segment manifest). Databases handle neither the size nor the bandwidth."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('65cbfe68-00ae-5895-a438-d90b73b48274', '00000000-0000-0000-0000-000000000001', 'mcq', 'After a mock interview, the highest-leverage habit is:', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','hld','lld','design-patterns','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
