VALUES ('a7a46dde-e9e5-50ea-9406-24c9df832a98', '65cbfe68-00ae-5895-a438-d90b73b48274', 1, $json${"prompt":"After a mock interview, the highest-leverage habit is:","multiple":false,"options":[{"id":"a","text":"Log every stumble — pattern gaps, communication misses — and drill those specific weaknesses next","is_correct":true},{"id":"b","text":"Immediately schedule another mock to stay warm","is_correct":false},{"id":"c","text":"Re-solve only the problems you already got right","is_correct":false},{"id":"d","text":"Memorize the exact solution to that one problem","is_correct":false}],"explanation":"Mocks are diagnostic instruments. Week 5's whole design is mock → weakness log → targeted drilling (that's Week 6). Repeating what you're good at feels productive but moves nothing."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

